import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"关键词回复","description":"","frontmatter":{"title":"关键词回复"},"headers":[],"relativePath":"solution/keywords.md","filePath":"solution/keywords.md","lastUpdated":1787948622000}'),o={name:"solution/keywords.md"};function l(i,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="关键词回复" tabindex="-1">关键词回复 <a class="header-anchor" href="#关键词回复" aria-label="Permalink to &quot;关键词回复&quot;">​</a></h1><p>关键词回复的优先级<strong>高于 AI</strong>：顾客消息命中关键词后，直接用你配置的话术回复，AI 不参与。适合活动话术、固定答案这类不想让 AI 自由发挥的场景。</p><p>入口：方案编辑器 → 「关键词设置」。</p><h2 id="三种匹配方式" tabindex="-1">三种匹配方式 <a class="header-anchor" href="#三种匹配方式" aria-label="Permalink to &quot;三种匹配方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>匹配方式</th><th>命中条件</th><th>例子</th></tr></thead><tbody><tr><td>包含</td><td>消息里含有关键词即命中</td><td>关键词「发货」命中「什么时候发货呀」</td></tr><tr><td>全匹配</td><td>消息与关键词完全一致才命中</td><td>关键词「1」只命中顾客单发「1」</td></tr><tr><td>正则表达式</td><td>消息匹配正则规则时命中</td><td>`^(在吗</td></tr></tbody></table><p>日常用「包含」就够了。「全匹配」适合让顾客回数字选选项的场景。正则给熟悉的人用，不熟悉就跳过。</p><h2 id="添加关键词" tabindex="-1">添加关键词 <a class="header-anchor" href="#添加关键词" aria-label="Permalink to &quot;添加关键词&quot;">​</a></h2><ol><li>点「添加关键词」。</li><li>填关键词、选匹配方式、写回复话术。</li><li>保存后立即生效。</li></ol><h2 id="批量导入" tabindex="-1">批量导入 <a class="header-anchor" href="#批量导入" aria-label="Permalink to &quot;批量导入&quot;">​</a></h2><p>支持 Excel 导入，一次最多 2000 行。页面上可下载模板，按模板格式填好后上传。大促前批量导入活动话术很实用。</p><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li><strong>别配太宽的词</strong>。「包含」匹配下，关键词「好」会命中「好的」「还没好吗」，把不该拦的消息拦下来。宁可具体一点。</li><li><strong>固定答案才用关键词</strong>。需要看上下文回答的问题（比如「这个和那个哪个好」）交给 AI 和知识库。</li><li><strong>活动结束记得停用</strong>。过期的活动话术继续命中会误导顾客。</li></ul><h2 id="和知识库的区别" tabindex="-1">和知识库的区别 <a class="header-anchor" href="#和知识库的区别" aria-label="Permalink to &quot;和知识库的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>关键词回复</th><th>知识库</th></tr></thead><tbody><tr><td>命中方式</td><td>字面匹配</td><td>语义检索，问法不同也能命中</td></tr><tr><td>回复内容</td><td>原样发送你写的话术</td><td>AI 参考资料组织语言</td></tr><tr><td>适合</td><td>固定话术、活动通知</td><td>政策、商品知识等需要理解的问题</td></tr></tbody></table>',14)])])}const _=a(o,[["render",l]]);export{u as __pageData,_ as default};
